// === Tab: mySketch ===
let isMobile = /iPhone|iPod|Android/i.test(navigator.userAgent);
let repel_radius;
let radius_;
let angle = 0;
let points = [];
const particles = 24000;
const attraction = 0.01;
const damping = 0.9;
const repel_strength = 28;
let cursorGlow = 0;

function setup() {
	describe("A rotating ocean-blue particle sphere with gradient background, interactive with mouse that has a glowing yellow cursor.");

	if (isMobile) {
		createCanvas(360, 360);
		radius_ = 160;
		repel_radius = 60;
	} else {
		createCanvas(900, 700);
		radius_ = 250;
		repel_radius = 90;
	}

	pixelDensity(1);
	strokeWeight(1.5);
	noCursor(); // Hide default cursor

	// initialize points array
	for (let i = 0; i < particles; i++) {
		points.push({
			index: i,
			pos: createVector(0, 0),
			vel: createVector(0, 0)
		});
	}
	// initiate them at angle = 0
	angle = 0; updateTargets();
	for (let p of points) p.vel.set(0, 0);
}

function draw() {
	// Draw deep ocean gradient background
	drawOceanGradient();
	translate(width / 2, height / 2);

	let mouse = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2);

	// Update cursor glow with smooth pulsing
	cursorGlow = sin(frameCount * 0.1) * 0.2 + 0.8;

	for (let p of points) {
		let i = p.index;

		// compute the rotating "home" position
		let homeX = sin(i + angle) * sin(i * i) * radius_;
		let homeY = cos(i * i) * radius_;
		let home = createVector(homeX, homeY);

		// spring force toward home ----
		let toHome = p5.Vector.sub(home, p.pos);
		let spring = toHome.mult(attraction);
		p.vel.add(spring);

		// mouse repulsion (strong when very close) ----
		let awayFromMouse = p5.Vector.sub(p.pos, mouse);
		let distSq = awayFromMouse.magSq();
		if (distSq > 0.1 && distSq < repel_radius * repel_radius) {
			let distance = sqrt(distSq);
			awayFromMouse.normalize();
			// natural falloff
			let repel = repel_strength * (1 - distance / repel_radius);
			awayFromMouse.mult(repel);
			p.vel.add(awayFromMouse);
		}

		// damping and move
		p.vel.mult(damping);
		p.pos.add(p.vel);

		// Calculate color based on position and movement for oceanic effect
		let depthFactor = map(p.pos.y, -radius_, radius_, 0.3, 1.0);
		let speed = p.vel.mag();
		let motionFactor = constrain(map(speed, 0, 2, 0.7, 1.3), 0.7, 1.3);

		// Ocean blue color palette with variations
		let r = 20 + 30 * depthFactor * motionFactor;
		let g = 100 + 80 * depthFactor * motionFactor;
		let b = 200 + 55 * depthFactor;

		// Add some sparkle/foam effect for faster particles
		if (speed > 1.5) {
			r = min(255, r + 80);
			g = min(255, g + 100);
			b = min(255, b + 40);
		}

		stroke(r, g, b, 220);
		point(p.pos.x, p.pos.y);
	}

	// Draw glowing yellow cursor particle
	drawGlowingCursor(mouse);

	angle += 0.01;
}

function drawGlowingCursor(mousePos) {
	push();
	translate(mousePos.x, mousePos.y);

	// Multiple layered circles for glow effect
	noStroke();

	// Outer glow (largest, most transparent)
	fill(255, 255, 200, 30 * cursorGlow);
	for (let i = 3; i > 0; i--) {
		let size = 20 + i * 8;
		circle(0, 0, size);
	}

	// Middle glow
	fill(255, 255, 150, 80 * cursorGlow);
	for (let i = 2; i > 0; i--) {
		var size = 12 + i * 4;
		circle(0, 0, size);
	}

	// Inner core (brightest)
	fill(255, 255, 100, 200 * cursorGlow);
	circle(0, 0, 8);

	// White hot center
	fill(255, 255, 255, 255);
	circle(0, 0, 3);

	pop();
}

function drawOceanGradient() {
	// Create deep ocean gradient from dark blue to lighter blue
	let topColor = color(5, 20, 40);     // Very deep blue
	let middleColor = color(10, 40, 80);  // Medium ocean blue
	let bottomColor = color(20, 60, 120); // Lighter ocean blue

	noStroke();
	for (let y = 0; y < height; y++) {
		let inter = map(y, 0, height, 0, 1);
		let c;
		if (y < height/2) {
			inter = map(y, 0, height/2, 0, 1);
			c = lerpColor(topColor, middleColor, inter);
		} else {
			inter = map(y, height/2, height, 0, 1);
			c = lerpColor(middleColor, bottomColor, inter);
		}
		fill(c);
		rect(0, y, width, 1);
	}
}

// put the initial positions right
function updateTargets() {
	for (let p of points) {
		var i = p.index;
		let x = sin(i + angle) * sin(i * i) * radius_;
		let y = cos(i * i) * radius_;
		p.pos.set(x, y);
	}
}

